def perplexity(sentence, k=0.0):
    sequence = ["<s>"] + tokenize(sentence) + ["</s>"]
    probabilities = [
        next_probability(h, w, k)
        for h, w in zip(sequence, sequence[1:])
    ]
    if any(p is None or p == 0 for p in probabilities):
        return math.inf
    return math.exp(-sum(math.log(p) for p in probabilities) / len(probabilities))

print("Test order:", TEST_TEXT)
for k in (0.0, 0.1, 0.5, 1.0):
    print(f"k={k:.1f}: perplexity = {perplexity(TEST_TEXT, k):.3f}")
assert math.isinf(perplexity(TEST_TEXT, 0.0))
assert math.isfinite(perplexity(TEST_TEXT, 1.0))
assert math.isinf(perplexity("we would like espresso", 1.0))
